#![feature(portable_simd)]
#![allow(dead_code)]
use std::simd::{Simd, StdFloat};
#[derive(Clone, Copy, PartialEq, Eq)]
enum Backend { Scalar, Portable4, NeonFma, Avx, AvxFma, Avx2Fma, Avx512 }
trait StoreTransform: Sync {
    fn scalar(&self, value: f32, index: usize) -> f32;
    fn vector<const N: usize>(&self, value: Simd<f32,N>, index: usize) -> Simd<f32,N>;
    fn vector_channel<const N: usize>(&self, value: Simd<f32,N>, index: usize, _: usize) -> Simd<f32,N> { self.vector(value,index) }
}
struct IdentityStore;
impl StoreTransform for IdentityStore {
    fn scalar(&self, v:f32,_:usize)->f32 {v}
    fn vector<const N:usize>(&self,v:Simd<f32,N>,_:usize)->Simd<f32,N>{v}
}
struct IndexStore;
impl StoreTransform for IndexStore {
    fn scalar(&self,v:f32,i:usize)->f32 {(v+(i%97) as f32/127.).max(0.)}
    fn vector<const N:usize>(&self,v:Simd<f32,N>,i:usize)->Simd<f32,N>{Simd::from_array(std::array::from_fn(|l|self.scalar(v[l],i+l)))}
}
struct PackedMatrix { values:Vec<f32>, inner:usize, columns:usize }
impl PackedMatrix {
    fn new(w:&[f32],k:usize,n:usize)->Self {
        let mut values=vec![0.;k*n.div_ceil(16)*16];
        for b in 0..n.div_ceil(16) {for j in 0..k {for l in 0..16 {if b*16+l<n {values[(b*k+j)*16+l]=w[j*n+b*16+l];}}}}
        Self{values,inner:k,columns:n}
    }
    fn matches(&self,k:usize,n:usize)->bool {self.inner==k&&self.columns==n}
    fn data(&self)->&[f32]{&self.values}
}
#[path="pointwise.rs"] mod kernel;
fn values(n:usize,seed:usize)->Vec<f32>{(0..n).map(|i|((i*37+seed*19)%113)as f32/71.-0.75).collect()}
fn bits(a:&[f32],b:&[f32]){assert_eq!(a.len(),b.len());for(i,(x,y))in a.iter().zip(b).enumerate(){assert_eq!(x.to_bits(),y.to_bits(),"output {i}: {x} vs {y}");}}
fn check(){
    for (m,k,n) in [(1,3,7),(3,385,17),(7,513,25),(9,769,129),(95,17,33),(97,65,17)] {
        let first=3;
        let a=values((first+m)*k,11);let w=values(k*n,13);let p=PackedMatrix::new(&w,k,n);let b=values(n,17);
        for bias in [b.as_slice(),&[]] {
            let mut expected=vec![0.;m*n];
            for r in 0..m {for c in 0..n {let mut v=bias.get(c).copied().unwrap_or(0.);for j in 0..k {v=a[(first+r)*k+j].mul_add(w[j*n+c],v);}expected[r*n+c]=IndexStore.scalar(v,(first+r)*n+c);}}
            for variant in 0..3 {
                let sentinel=f32::from_bits(0x7fc0_1234);let mut out=vec![sentinel;m*n+6];
                kernel::probe(variant,&a,bias,&p,&mut out[3..3+m*n],first,k,n,&IndexStore);
                bits(&out[3..3+m*n],&expected);
                assert!(out[..3].iter().chain(&out[3+m*n..]).all(|v|v.to_bits()==sentinel.to_bits()));
            }
        }
    }
    println!("oracle checks passed: six geometries, bias/no bias, three variants, global fused indices and guards");
}
fn pin(){
    unsafe {
        unsafe extern "system" {fn GetCurrentProcess()->*mut std::ffi::c_void; fn GetProcessAffinityMask(p:*mut std::ffi::c_void,a:*mut usize,s:*mut usize)->i32;fn SetProcessAffinityMask(p:*mut std::ffi::c_void,m:usize)->i32;}
        let p=GetCurrentProcess();let(mut a,mut s)=(0,0);assert_ne!(GetProcessAffinityMask(p,&mut a,&mut s),0);assert_ne!(a,0);assert_ne!(SetProcessAffinityMask(p,a.isolate_lowest_one()),0);
    }
}
fn bench(){
    pin();let deadline=std::time::Instant::now();
    for (m,k,n) in [(96,384,768),(960,512,1024),(480,1536,768)] {
        let a=values(m*k,41);let w=values(k*n,43);let b=values(n,47);let p=PackedMatrix::new(&w,k,n);
        let mut out=[vec![0.;m*n],vec![0.;m*n],vec![0.;m*n]];
        for v in 0..3 {kernel::probe(v,&a,&b,&p,&mut out[v],0,k,n,&IdentityStore);}
        bits(&out[0],&out[1]);bits(&out[0],&out[2]);let mut times=[[0.;3];3];
        for sample in 0..3 {
            for v in match sample {0=>[0,1,2],1=>[2,1,0],_=>[1,0,2]} {
                let start=std::time::Instant::now();kernel::probe(v,&a,&b,&p,std::hint::black_box(&mut out[v]),0,k,n,&IdentityStore);times[v][sample]=start.elapsed().as_secs_f64()*1000.;
            }
            bits(&out[0],&out[1]);bits(&out[0],&out[2]);
        }
        println!("tile_probe {{\"rows\":{m},\"inner\":{k},\"columns\":{n},\"baseline_ms\":{:?},\"tile8_ms\":{:?},\"tile24_ms\":{:?},\"equal_bits\":true,\"warmups\":1,\"measured\":3}}",times[0],times[1],times[2]);
        assert!(deadline.elapsed().as_secs()<10);
    }
}
fn main(){assert!(is_x86_feature_detected!("avx2")&&is_x86_feature_detected!("fma"));match std::env::args().nth(1).as_deref(){Some("check")=>check(),Some("bench")=>bench(),_=>panic!("use check or bench")}}

