pub(super) fn probe(v:usize,a:&[f32],b:&[f32],p:&PackedMatrix,o:&mut[f32],first:usize,k:usize,n:usize,s:&impl StoreTransform){
    let rows=o.len()/n;
    match v {
        0=>execute(Backend::Avx2Fma,a,b,p,o,first,k,n,s),
        1=>unsafe{tile8::execute(&a[first*k..(first+rows)*k],b,p,o,first,k,n,s)},
        2=>unsafe{tile24::execute(&a[first*k..(first+rows)*k],b,p,o,first,k,n,s)},
        _=>unreachable!()
    }
}

tile8.rs.source:
//! Eight-row AVX2 pointwise tiles over each eight-column packed-panel half.
//!
//! The narrower output tile trades extra scalar broadcasts for fewer weight
//! loads per output and eight independent FMA chains. Both panel halves keep
//! the existing sixteen-column packing and bias-first ascending-K reduction.
use super::*;
use std::arch::{asm, x86_64::__m256};

const TILE_ROWS: usize = 8;

macro_rules! tile8 {
    ($rows:expr, $panel:expr, $initial:expr, $inner:expr) => {{
        let rows: [&[f32]; TILE_ROWS] = $rows;
        let panel: &[f32] = $panel;
        // SAFETY: both vector types represent eight f32 lanes identically.
        let initial = unsafe { std::mem::transmute::<Simd<f32, 8>, __m256>($initial) };
        let mut a0 = initial;
        let mut a1 = initial;
        let mut a2 = initial;
        let mut a3 = initial;
        let mut a4 = initial;
        let mut a5 = initial;
        let mut a6 = initial;
        let mut a7 = initial;
        // SAFETY: execute establishes inner > 0 and eight full input rows.
        // A panel-half starts at offset zero or eight in an inner * 16 span;
        // its final eight-f32 load ends within that span. k advances from zero
        // to inner without dereferencing beyond either checked allocation.
        // Every accumulator has one ascending-K FMA chain, initialized with
        // bias. Assembly writes only its declared registers and flags.
        unsafe {
            asm!(
                "xor {k:e}, {k:e}",
                ".p2align 4",
                "2:",
                "vmovups {w}, [{weights}]",
                "vbroadcastss {v}, [{p0} + {k} * 4]",
                "vfmadd231ps {a0}, {v}, {w}",
                "vbroadcastss {v}, [{p1} + {k} * 4]",
                "vfmadd231ps {a1}, {v}, {w}",
                "vbroadcastss {v}, [{p2} + {k} * 4]",
                "vfmadd231ps {a2}, {v}, {w}",
                "vbroadcastss {v}, [{p3} + {k} * 4]",
                "vfmadd231ps {a3}, {v}, {w}",
                "vbroadcastss {v}, [{p4} + {k} * 4]",
                "vfmadd231ps {a4}, {v}, {w}",
                "vbroadcastss {v}, [{p5} + {k} * 4]",
                "vfmadd231ps {a5}, {v}, {w}",
                "vbroadcastss {v}, [{p6} + {k} * 4]",
                "vfmadd231ps {a6}, {v}, {w}",
                "vbroadcastss {v}, [{p7} + {k} * 4]",
                "vfmadd231ps {a7}, {v}, {w}",
                "inc {k}",
                "add {weights}, 64",
                "cmp {k}, {inner}",
                "jb 2b",
                a0 = inout(ymm_reg) a0, a1 = inout(ymm_reg) a1,
                a2 = inout(ymm_reg) a2, a3 = inout(ymm_reg) a3,
                a4 = inout(ymm_reg) a4, a5 = inout(ymm_reg) a5,
                a6 = inout(ymm_reg) a6, a7 = inout(ymm_reg) a7,
                w = out(ymm_reg) _, v = out(ymm_reg) _,
                p0 = in(reg) rows[0].as_ptr(), p1 = in(reg) rows[1].as_ptr(),
                p2 = in(reg) rows[2].as_ptr(), p3 = in(reg) rows[3].as_ptr(),
                p4 = in(reg) rows[4].as_ptr(), p5 = in(reg) rows[5].as_ptr(),
                p6 = in(reg) rows[6].as_ptr(), p7 = in(reg) rows[7].as_ptr(),
                weights = inout(reg) panel.as_ptr() => _,
                inner = in(reg) $inner, k = out(reg) _,
                options(nostack, readonly),
            );
        }
        // SAFETY: arrays preserve the identical eight-f32 vector layout.
        unsafe {
            std::mem::transmute::<[__m256; TILE_ROWS], [Simd<f32, 8>; TILE_ROWS]>([
                a0, a1, a2, a3, a4, a5, a6, a7,
            ])
        }
    }};
}

/// Caller must establish AVX2/FMA; checked spans bound all assembly loads.
#[target_feature(enable = "avx2,fma")]
#[allow(clippy::too_many_arguments)]
pub(super) unsafe fn execute(
    input: &[f32],
    bias: &[f32],
    packed: &PackedMatrix,
    output: &mut [f32],
    first: usize,
    inner: usize,
    columns: usize,
    store: &impl StoreTransform,
) {
    assert!(inner > 0 && columns > 0 && packed.matches(inner, columns));
    assert_eq!(output.len() % columns, 0);
    assert!(bias.is_empty() || bias.len() == columns);
    let rows = output.len() / columns;
    assert_eq!(
        input.len(),
        rows.checked_mul(inner)
            .expect("pointwise input size overflow")
    );
    let group_rows = avx_group_rows(inner, columns);
    for group in (0..rows).step_by(group_rows) {
        let count = (rows - group).min(group_rows);
        let input = &input[group * inner..(group + count) * inner];
        for (block, panel) in packed.data().chunks_exact(inner * 16).enumerate() {
            let column = block * 16;
            for half in [0, 8] {
                let column = column + half;
                if column >= columns {
                    continue;
                }
                let initial = initial::<8>(bias, column);
                let panel = &panel[half..];
                for tile in (0..count).step_by(TILE_ROWS) {
                    // Duplicate the final valid input row in incomplete tiles;
                    // only the valid row results reach the final epilogue.
                    let inputs = std::array::from_fn(|r| {
                        let start = (tile + r).min(count - 1) * inner;
                        &input[start..start + inner]
                    });
                    let [a0, a1, a2, a3, a4, a5, a6, a7] =
                        tile8!(inputs, panel, initial, inner);
                    macro_rules! store {
                        ($r:literal, $a:ident) => {
                            if tile + $r < count {
                                store_row(
                                    $a,
                                    output,
                                    group + tile + $r,
                                    column,
                                    columns,
                                    first,
                                    store,
                                );
                            }
                        };
                    }
                    store!(0, a0);
                    store!(1, a1);
                    store!(2, a2);
                    store!(3, a3);
                    store!(4, a4);
                    store!(5, a5);
                    store!(6, a6);
                    store!(7, a7);
                }
            }
        }
    }
}

tile24.rs.source:
//! Four-row by twenty-four-column AVX2 pointwise tiles.
//!
//! Twelve independent accumulators share four input broadcasts across three
//! eight-column streams. The streams retain the established sixteen-column
//! packed format, including its zero-padded final output-channel panel.
use super::*;
use std::arch::{asm, x86_64::__m256};

const TILE_ROWS: usize = 4;
const GROUP_ROWS: usize = 96;

macro_rules! tile24 {
    ($rows:expr, $panels:expr, $initial:expr, $inner:expr) => {{
        let rows: [&[f32]; TILE_ROWS] = $rows;
        let panels: [&[f32]; 3] = $panels;
        // SAFETY: both vector types represent eight f32 lanes identically.
        let [low, middle, high] = unsafe {
            std::mem::transmute::<[Simd<f32, 8>; 3], [__m256; 3]>($initial)
        };
        let (mut a0, mut b0, mut c0) = (low, middle, high);
        let (mut a1, mut b1, mut c1) = (low, middle, high);
        let (mut a2, mut b2, mut c2) = (low, middle, high);
        let (mut a3, mut b3, mut c3) = (low, middle, high);
        // SAFETY: execute establishes inner > 0, four complete input rows and
        // three checked packed-half spans. k traverses 0..inner, while offset
        // advances by sixteen floats per step. Each eight-f32 vector load
        // therefore remains within its checked span. The assembly modifies
        // only declared registers/flags and preserves bias-first ascending-K
        // FMA order for every output. Twelve accumulators, three weight vectors
        // and one broadcast use exactly the sixteen architectural YMM registers.
        unsafe {
            asm!(
                "xor {k:e}, {k:e}",
                "xor {offset:e}, {offset:e}",
                ".p2align 4",
                "2:",
                "vmovups {w0}, [{weights0} + {offset}]",
                "vmovups {w1}, [{weights1} + {offset}]",
                "vmovups {w2}, [{weights2} + {offset}]",
                "vbroadcastss {v}, [{p0} + {k} * 4]",
                "vfmadd231ps {a0}, {v}, {w0}",
                "vfmadd231ps {b0}, {v}, {w1}",
                "vfmadd231ps {c0}, {v}, {w2}",
                "vbroadcastss {v}, [{p1} + {k} * 4]",
                "vfmadd231ps {a1}, {v}, {w0}",
                "vfmadd231ps {b1}, {v}, {w1}",
                "vfmadd231ps {c1}, {v}, {w2}",
                "vbroadcastss {v}, [{p2} + {k} * 4]",
                "vfmadd231ps {a2}, {v}, {w0}",
                "vfmadd231ps {b2}, {v}, {w1}",
                "vfmadd231ps {c2}, {v}, {w2}",
                "vbroadcastss {v}, [{p3} + {k} * 4]",
                "vfmadd231ps {a3}, {v}, {w0}",
                "vfmadd231ps {b3}, {v}, {w1}",
                "vfmadd231ps {c3}, {v}, {w2}",
                "inc {k}",
                "add {offset}, 64",
                "cmp {k}, {inner}",
                "jb 2b",
                a0 = inout(ymm_reg) a0, b0 = inout(ymm_reg) b0, c0 = inout(ymm_reg) c0,
                a1 = inout(ymm_reg) a1, b1 = inout(ymm_reg) b1, c1 = inout(ymm_reg) c1,
                a2 = inout(ymm_reg) a2, b2 = inout(ymm_reg) b2, c2 = inout(ymm_reg) c2,
                a3 = inout(ymm_reg) a3, b3 = inout(ymm_reg) b3, c3 = inout(ymm_reg) c3,
                w0 = out(ymm_reg) _, w1 = out(ymm_reg) _, w2 = out(ymm_reg) _,
                v = out(ymm_reg) _,
                p0 = in(reg) rows[0].as_ptr(), p1 = in(reg) rows[1].as_ptr(),
                p2 = in(reg) rows[2].as_ptr(), p3 = in(reg) rows[3].as_ptr(),
                weights0 = in(reg) panels[0].as_ptr(),
                weights1 = in(reg) panels[1].as_ptr(),
                weights2 = in(reg) panels[2].as_ptr(),
                inner = in(reg) $inner, k = out(reg) _, offset = out(reg) _,
                options(nostack, readonly),
            );
        }
        // SAFETY: arrays preserve the identical eight-f32 vector layout.
        unsafe {
            std::mem::transmute::<[[__m256; 3]; TILE_ROWS], [[Simd<f32, 8>; 3]; TILE_ROWS]>([
                [a0, b0, c0], [a1, b1, c1], [a2, b2, c2], [a3, b3, c3],
            ])
        }
    }};
}

/// Caller must establish AVX2/FMA; checked spans bound all assembly loads.
#[target_feature(enable = "avx2,fma")]
#[allow(clippy::too_many_arguments)]
pub(super) unsafe fn execute(
    input: &[f32],
    bias: &[f32],
    packed: &PackedMatrix,
    output: &mut [f32],
    first: usize,
    inner: usize,
    columns: usize,
    store: &impl StoreTransform,
) {
    assert!(inner > 0 && columns > 0 && packed.matches(inner, columns));
    assert_eq!(output.len() % columns, 0);
    assert!(bias.is_empty() || bias.len() == columns);
    let rows = output.len() / columns;
    assert_eq!(
        input.len(),
        rows.checked_mul(inner)
            .expect("pointwise input size overflow")
    );
    let last_half = (columns - 1) / 8 * 8;
    for group in (0..rows).step_by(GROUP_ROWS) {
        let count = (rows - group).min(GROUP_ROWS);
        let input = &input[group * inner..(group + count) * inner];
        for column in (0..columns).step_by(24) {
            // Invalid output halves reuse the last valid packed half as dummy
            // input. store_row rejects their logical output-channel indices.
            let panels = std::array::from_fn(|half| {
                let channel = (column + half * 8).min(last_half);
                let offset = channel / 16 * inner * 16 + channel % 16;
                let length = (inner - 1) * 16 + 8;
                &packed.data()[offset..offset + length]
            });
            let initial = [
                initial::<8>(bias, column),
                initial::<8>(bias, column + 8),
                initial::<8>(bias, column + 16),
            ];
            for tile in (0..count).step_by(TILE_ROWS) {
                // Only valid rows reach the final epilogue; the reduction may
                // safely duplicate the last valid row of an incomplete tile.
                let inputs = std::array::from_fn(|r| {
                    let start = (tile + r).min(count - 1) * inner;
                    &input[start..start + inner]
                });
                let [[a0, b0, c0], [a1, b1, c1], [a2, b2, c2], [a3, b3, c3]] =
                    tile24!(inputs, panels, initial, inner);
                macro_rules! store {
                    ($r:literal, $a:ident, $b:ident, $c:ident) => {
                        if tile + $r < count {
                            let row = group + tile + $r;
                            store_row($a, output, row, column, columns, first, store);
                            store_row($b, output, row, column + 8, columns, first, store);
                            store_row($c, output, row, column + 16, columns, first, store);
                        }
                    };
                }
                store!(0, a0, b0, c0);
                store!(1, a1, b1, c1);
                store!(2, a2, b2, c2);
                store!(3, a3, b3, c3);
            }
        }
    }
}

avx2.rs.source:
//! Full-K AVX2 tiles with an inline, register-contained reduction loop.
use super::*;
use std::arch::{asm, x86_64::__m256};

// Explicit register operands keep loop geometry and epilogue state outside K
// without imposing a function/return-buffer boundary on every six-row tile.
macro_rules! tile {
    ($rows:expr, $panel:expr, $low:expr, $high:expr, $inner:expr) => {{
        let rows: [&[f32]; ROWS] = $rows;
        let panel: &[f32] = $panel;
        // SAFETY: both vector representations hold the same eight f32 lanes.
        let (low, high) = unsafe {
            (std::mem::transmute::<Simd<f32, 8>, __m256>($low),
             std::mem::transmute::<Simd<f32, 8>, __m256>($high))
        };
        let (mut a0, mut b0) = (low, high);
        let (mut a1, mut b1) = (low, high);
        let (mut a2, mut b2) = (low, high);
        let (mut a3, mut b3) = (low, high);
        let (mut a4, mut b4) = (low, high);
        let (mut a5, mut b5) = (low, high);
        // SAFETY: the AVX2/FMA entry checks inner > 0. Each row contains inner
        // floats; panel contains inner * 16. k starts at zero and advances to
        // inner, so every scalar/vector load stays within its checked span.
        // The assembly only reads memory, declares every modified register and
        // flags, and performs the same bias-first ascending-K FMA chain.
        unsafe {
            asm!(
                "xor {k:e}, {k:e}",
                ".p2align 4",
                "2:",
                "vmovups {w0}, [{weights}]",
                "vmovups {w1}, [{weights} + 32]",
                "vbroadcastss {v}, [{p0} + {k} * 4]",
                "vfmadd231ps {a0}, {v}, {w0}",
                "vfmadd231ps {b0}, {v}, {w1}",
                "vbroadcastss {v}, [{p1} + {k} * 4]",
                "vfmadd231ps {a1}, {v}, {w0}",
                "vfmadd231ps {b1}, {v}, {w1}",
                "vbroadcastss {v}, [{p2} + {k} * 4]",
                "vfmadd231ps {a2}, {v}, {w0}",
                "vfmadd231ps {b2}, {v}, {w1}",
                "vbroadcastss {v}, [{p3} + {k} * 4]",
                "vfmadd231ps {a3}, {v}, {w0}",
                "vfmadd231ps {b3}, {v}, {w1}",
                "vbroadcastss {v}, [{p4} + {k} * 4]",
                "vfmadd231ps {a4}, {v}, {w0}",
                "vfmadd231ps {b4}, {v}, {w1}",
                "vbroadcastss {v}, [{p5} + {k} * 4]",
                "vfmadd231ps {a5}, {v}, {w0}",
                "vfmadd231ps {b5}, {v}, {w1}",
                "inc {k}",
                "add {weights}, 64",
                "cmp {k}, {inner}",
                "jb 2b",
                a0 = inout(ymm_reg) a0, b0 = inout(ymm_reg) b0,
                a1 = inout(ymm_reg) a1, b1 = inout(ymm_reg) b1,
                a2 = inout(ymm_reg) a2, b2 = inout(ymm_reg) b2,
                a3 = inout(ymm_reg) a3, b3 = inout(ymm_reg) b3,
                a4 = inout(ymm_reg) a4, b4 = inout(ymm_reg) b4,
                a5 = inout(ymm_reg) a5, b5 = inout(ymm_reg) b5,
                w0 = out(ymm_reg) _, w1 = out(ymm_reg) _, v = out(ymm_reg) _,
                p0 = in(reg) rows[0].as_ptr(), p1 = in(reg) rows[1].as_ptr(),
                p2 = in(reg) rows[2].as_ptr(), p3 = in(reg) rows[3].as_ptr(),
                p4 = in(reg) rows[4].as_ptr(), p5 = in(reg) rows[5].as_ptr(),
                weights = inout(reg) panel.as_ptr() => _,
                inner = in(reg) $inner, k = out(reg) _,
                options(nostack, readonly),
            );
        }
        // SAFETY: arrays of the two eight-f32 vector types have identical layout.
        unsafe { std::mem::transmute::<[[__m256; 2]; ROWS], [[Simd<f32, 8>; 2]; ROWS]>(
            [[a0, b0], [a1, b1], [a2, b2], [a3, b3], [a4, b4], [a5, b5]]) }
    }};
}

/// Caller must establish AVX2/FMA; all data spans are checked before assembly.
#[target_feature(enable = "avx2,fma")]
#[allow(clippy::too_many_arguments)]
pub(super) unsafe fn execute(
    input: &[f32],
    bias: &[f32],
    packed: &PackedMatrix,
    output: &mut [f32],
    first: usize,
    inner: usize,
    columns: usize,
    store: &impl StoreTransform,
) {
    assert!(inner > 0 && columns > 0 && packed.matches(inner, columns));
    assert_eq!(output.len() % columns, 0);
    assert!(bias.is_empty() || bias.len() == columns);
    let rows = output.len() / columns;
    assert_eq!(
        input.len(),
        rows.checked_mul(inner)
            .expect("pointwise input size overflow")
    );
    let group_rows = avx_group_rows(inner, columns);
    for group in (0..rows).step_by(group_rows) {
        let count = (rows - group).min(group_rows);
        let input = &input[group * inner..(group + count) * inner];
        for (block, panel) in packed.data().chunks_exact(inner * 16).enumerate() {
            let column = block * 16;
            let low = initial::<8>(bias, column);
            let high = initial::<8>(bias, column + 8);
            for tile in (0..count).step_by(ROWS) {
                let [[a0, b0], [a1, b1], [a2, b2], [a3, b3], [a4, b4], [a5, b5]] = tile!(
                    row_inputs(input, tile, count, inner),
                    panel,
                    low,
                    high,
                    inner
                );
                // Named rows allow direct stores without an addressable tile
                // array. Tail checks never enter the reduction loop.
                macro_rules! store {
                    ($r:literal, $a:ident, $b:ident) => {
                        if tile + $r < count {
                            store_row($a, output, group + tile + $r, column, columns, first, store);
                            store_row(
                                $b,
                                output,
                                group + tile + $r,
                                column + 8,
                                columns,
                                first,
                                store,
                            );
                        }
                    };
                }
                store!(0, a0, b0);
                store!(1, a1, b1);
                store!(2, a2, b2);
                store!(3, a3, b3);
                store!(4, a4, b4);
                store!(5, a5, b5);
            }
        }
    }
}

